"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["24143"],{38679(e){e.exports=JSON.parse('{"id":"FIN-050","slug":"interest-rate","term":"Interest Rate","also_known_as":[],"difficulty":"Beginner","definition":"An interest rate is the percentage charged on borrowed money, or paid on saved money, over a period of time, usually a year.","explanation":["An interest rate turns the cost of borrowing into a simple percentage. If a loan has an interest rate of 8% a year, borrowing 1,000 for a year costs about 80 in interest.","Interest rates vary widely. A government savings product might pay 3%, a mortgage might charge 5%, a car loan 8% and a credit card more than 20%. The differences reflect risk, loan length, whether the loan is secured by an asset and the lender\'s costs and profit.","Across an economy, interest rates are influenced by the central bank, which sets a key policy rate. When the central bank raises its rate to fight inflation, banks usually raise the rates they charge borrowers and pay savers. When it cuts rates to support the economy, borrowing becomes cheaper.","When comparing interest rates, it helps to check what the rate includes. Some rates include fees and the effect of compounding, while others do not. Terms such as APR and APY exist so that borrowers and savers can compare products on a fair basis."],"note":"","total":1500,"prev":{"slug":"interest-only-loan","term":"Interest-Only Loan"},"next":{"slug":"interest-rate-cap","term":"Interest Rate Cap"}}')}}]);